ALTER TABLE outbox_events ADD COLUMN IF NOT EXISTS last_error text NULL, ADD COLUMN IF NOT EXISTS next_attempt_at timestamptz NULL, ADD COLUMN IF NOT EXISTS locked_at timestamptz NULL, ADD COLUMN IF NOT EXISTS locked_by text NULL, ADD COLUMN IF NOT EXISTS failed_at timestamptz NULL;
CREATE TABLE IF NOT EXISTS email_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), outbox_event_id uuid NOT NULL REFERENCES outbox_events(id) ON DELETE RESTRICT, email_type text NOT NULL, recipient text NOT NULL, provider text NOT NULL, provider_message_id text NULL, status text NOT NULL CHECK (status IN ('PENDING','SENDING','SENT','FAILED')), attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0), last_error text NULL, sent_at timestamptz NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(outbox_event_id, email_type, recipient));
CREATE INDEX IF NOT EXISTS outbox_ready_idx ON outbox_events(next_attempt_at, created_at) WHERE processed_at IS NULL AND failed_at IS NULL;
